import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../app_helpers.dart';
import '../database/db_helper.dart';
class Statistics extends StatelessWidget{const Statistics({super.key});@override Widget build(BuildContext c)=>FutureBuilder(future:Future.wait([DB.i.tx(type:'Pemasukan'),DB.i.all('siswa')]),builder:(c,s){if(!s.hasData)return const Scaffold(body:Center(child:CircularProgressIndicator()));final tx=s.data![0] as List<Map<String,dynamic>>,students=s.data![1] as List<Map<String,dynamic>>;final sums=<int,double>{};for(final e in tx){if(e['id_siswa']!=null){final id=e['id_siswa'] as int;sums[id]=(sums[id]??0)+(e['jumlah'] as num).toDouble();}}final total=sums.values.fold<double>(0,(a,b)=>a+b);return Scaffold(appBar:AppBar(title:const Text('Statistik pembayaran')),body:ListView(padding:const EdgeInsets.all(18),children:[card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('TOTAL PEMBAYARAN SISWA'),Text(money.format(total),style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold,color:navy)),Text('${students.length} siswa terdaftar')])),label('Total per siswa'),card(Column(children:students.map((e){final n=sums[e['id_siswa']]??0;return ListTile(title:Text(e['nama_siswa']),trailing:Text(money.format(n),style:const TextStyle(fontWeight:FontWeight.bold)));}).toList()))]));});}
